export type Steps = Parameters<ReturnType<typeof registerFauxProvider>["setResponses"]>[0];
export function providerConfig(model: ReturnType<ReturnType<typeof registerFauxProvider>["getModel"]>) {
  if (!model) throw new Error("Missing faux model");
  const { id, name, api, baseUrl, reasoning, input, cost, contextWindow, maxTokens } = model;
  return { id: model.provider, api, baseUrl,
    models: [{ id, name, reasoning, input, cost, contextWindow, maxTokens }] };
}
export async function harness(steps: Steps = [], patch: ConfigPatch = {}, factories: ExtensionFactory[] = []) {
  const dir = mkdtempSync(join(tmpdir(), "polaris-agentd-"));
  const faux = registerFauxProvider({ models: [{ id: "test", reasoning: true }], tokensPerSecond: Infinity });
  faux.setResponses(steps);
  const model = faux.getModel();
  const config = mergeConfig(loadConfig(), {
    sessionDir: join(dir, "sessions"), defaultModel: { provider: model.provider, id: model.id },
    providers: [providerConfig(model)], tools: [],
    // SDK behavior tests opt into execution; permission tests explicitly choose their mode.
    permissions: { ...loadConfig().permissions, defaultMode: "auto-all" }, ...patch,
  });
  const events: ProtocolEvent[] = [];
  const logs: string[] = [];
  const daemon = await Daemon.create(config, (value) => {
    if (value.type === "event") events.push(value);
  }, (line) => logs.push(line), { factories });
  await daemon.models.apply(config, { [model.provider]: "test-secret-key-7654321" });
  let nextId = 0;
  const request = (method: string, params: object = {}) => daemon.handle({ id: ++nextId, method, params });
  return { dir, faux, daemon, events, logs, request,
    async close() {
      await daemon.shutdown();
      faux.unregister();
      rmSync(dir, { recursive: true, force: true });
    },
  };
}
export function result<T>(response: Response): T {
  if (!response.ok) throw new Error(JSON.stringify(response));
  return response.result as T;
}
export async function until(predicate: () => boolean): Promise<void> {
  const end = Date.now() + 5000;
  while (!predicate()) {
    if (Date.now() > end) throw new Error("Timed out waiting for condition");
    await delay(5);
  }
}
#!/usr/bin/env node
import { format } from "node:util";
import { loadConfig } from "./config/load.ts";
import { Daemon } from "./daemon.ts";
import { Logger } from "./log.ts";
import { Redactor } from "./models/credentials.ts";
import { publicError } from "./protocol/errors.ts";
import { JsonlReader, JsonlWriter } from "./protocol/jsonl.ts";

const redactor = new Redactor();
const output = new JsonlWriter(process.stdout, redactor);
const logs = new JsonlWriter(process.stderr, redactor);
// Use the same ordered writer for structured logs, without parsing user input as logs.
const writeLog = (line: string) => logs.send(JSON.parse(line));
let logger = new Logger(() => "error", redactor, writeLog);

// SDK/resource diagnostics must never corrupt the stdout protocol.
for (const method of ["log", "info", "warn", "error", "debug"] as const) {
  console[method] = (...args: unknown[]) => {
    logger.log(method === "error" ? "error" : "debug", redactor.text(format(...args)));
  };
}

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  if (args.length && (args.length !== 2 || args[0] !== "--config")) {
    throw new Error("Expected --config <path>");
  }
  const daemon = await Daemon.create(loadConfig(args[1] ?? process.env.POLARIS_AGENTD_CONFIG),
    (value) => output.send(value), writeLog, { redactor });
  logger = daemon.logger;
  let shutdown: Promise<void> | undefined;
  const reader = new JsonlReader(() => daemon.config.maxLineBytes, (value) => {
    void daemon.handle(value).then((response) => output.send(response));
  }, (error) => output.send({ type: "response", id: null, ok: false, error: publicError(error) }));
  const onData = (chunk: Buffer) => reader.push(chunk);
  const stop = () => {
    if (shutdown) return shutdown;
    process.stdin.off("data", onData);
    process.stdin.pause();
    reader.end();
    shutdown = (async () => {
      await daemon.shutdown();
      logger.log("info", "Daemon stopped");
      await output.flush();
      await logs.flush();
    })();
    return shutdown;
  };
  await new Promise<void>((resolve, reject) => {
    const finish = () => { void stop().then(resolve, reject); };
    process.stdin.on("data", onData);
    process.stdin.once("end", finish);
    process.stdin.once("error", finish);
    process.once("SIGTERM", finish);
    process.once("SIGINT", finish);
  });
}

try {
  await main();
} catch (error) {
  const safe = publicError(error);
  logger.log("error", safe.message, { code: safe.code, paths: safe.paths });
  process.exitCode = 1;
  await logs.flush().catch(() => undefined);
}
import { mkdirSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import {
  createAgentSession, DefaultResourceLoader, SessionManager, SettingsManager,
  type ExtensionFactory,
} from "@earendil-works/pi-coding-agent";
import type { Config } from "../config/schema.ts";
import type { Models } from "../models/runtime.ts";
import type { SessionOptions } from "../protocol/schema.ts";
import { contextFiles, expandPath } from "../extensions/resources.ts";
import { activateTools, profileTools } from "./options.ts";
import { DaemonError } from "../protocol/errors.ts";

export async function createSession(
  config: Config, models: Models, factories: ExtensionFactory[], sessionId?: string, requestedCwd?: string, options: SessionOptions = {}, mandatoryFactories: (cwd: string) => ExtensionFactory[] = () => [],
) {
  const runtime = models.runtime;
  const tools = profileTools(config, options.toolProfile ?? config.defaultToolProfile);
  mkdirSync(config.sessionDir, { recursive: true });
  const cwd = resolve(requestedCwd ?? process.cwd());
  let manager: SessionManager;
  if (sessionId) {
    // Exact lookup, never treat an untrusted session id as a filesystem path.
    if (!/^[a-zA-Z0-9-]+$/.test(sessionId)) throw new DaemonError("INVALID_SESSION_ID", "Invalid session id");
    const path = (await SessionManager.listAll(config.sessionDir)).find((info) => info.id === sessionId)?.path;
    if (!path) throw new DaemonError("SESSION_NOT_FOUND", "Persisted session not found");
    manager = SessionManager.open(path, config.sessionDir, requestedCwd ? cwd : undefined);
  } else manager = SessionManager.create(cwd, config.sessionDir);
  try {
    if (!statSync(manager.getCwd()).isDirectory()) throw new Error();
  } catch {
    throw new DaemonError("INVALID_CWD", "Working directory does not exist");
  }
  const model = runtime.getModel((options.model ?? config.defaultModel).provider, (options.model ?? config.defaultModel).id);
  if (!model) throw new DaemonError("MODEL_NOT_FOUND", "Configured default model does not exist");
  const settingsManager = SettingsManager.inMemory({
    compaction: config.compaction, retry: config.retry, cacheWarming: "off",
  });
  const agentDir = join(config.sessionDir, ".resources");
  const resourceLoader = new DefaultResourceLoader({
    cwd: manager.getCwd(), agentDir, settingsManager,
    // Only host-assembled executable extensions. Standard AGENTS.md/skills still load.
    noExtensions: true, noThemes: true,
    extensionFactories: [...(config.extensions.enabled ? factories : []), ...mandatoryFactories(manager.getCwd())],
    additionalSkillPaths: config.skills.paths.map(expandPath),
    agentsFilesOverride: (base) => contextFiles(manager.getCwd(), base),
  });
  await resourceLoader.reload();
  const { session } = await createAgentSession({
    cwd: manager.getCwd(), agentDir, model, modelRuntime: runtime,
    thinkingLevel: options.thinkingLevel ?? config.thinkingLevel,
    // Register the configured universe so idle profile changes can enable tools.
    tools: [...new Set(Object.values(config.toolProfiles).flat())],
    settingsManager, sessionManager: manager, resourceLoader,
  });
  try {
    await session.bindExtensions({ mode: "rpc" });
    activateTools(session, tools);
    return session;
  } catch (error) {
    session.dispose();
    throw error;
  }
}
import type { AgentSession } from "@earendil-works/pi-coding-agent";
import { Value } from "typebox/value";
import type { Config } from "../config/schema.ts";
import { DaemonError } from "../protocol/errors.ts";
import { SessionOptionsSchema, type SessionOptions } from "../protocol/schema.ts";

export function profileTools(config: Config, profile: string): string[] {
  if (!Object.hasOwn(config.toolProfiles, profile)) {
    throw new DaemonError("TOOL_PROFILE_NOT_FOUND", "Unknown tool profile");
  }
  return config.toolProfiles[profile];
}
export function checkTools(session: AgentSession, tools: string[]): void {
  const known = new Set(session.getAllTools().map((tool) => tool.name));
  if (tools.some((name) => !known.has(name))) {
    throw new DaemonError("TOOL_PROFILE_UNAVAILABLE", "Profile contains tools unavailable in this session; reopen required");
  }
}
export function activateTools(session: AgentSession, tools: string[]): void {
  checkTools(session, tools);
  session.setActiveToolsByName(tools);
  const active = session.getActiveToolNames();
  if (active.length !== tools.length || tools.some((name) => !active.includes(name))) {
    throw new DaemonError("TOOL_PROFILE_UNAVAILABLE", "SDK cannot activate the requested tool profile");
  }
