  request("steer", { sessionId: text, text }),
  request("followUp", { sessionId: text, text }),
  request("abort", { sessionId: text }), request("close", { sessionId: text }),
  Type.Object({ id, method: Type.Literal("config.apply"), params: Type.Object({
