pub(super) fn persist() {
    if persist_checked().is_err() { eprintln!("[provider] ProviderStoreWriteFailed"); }
}

pub(super) fn persist_checked() -> Result<(), String> {
    let Some(path) = shared_path() else { return Ok(()); };
    let _io = IO_LOCK.lock();
    let _file = credential_file::FileLock::acquire(&path)?;
    let disk = credential_file::read_root(&path)?;
    let mut credentials = disk.get("credentials").cloned().unwrap_or_else(|| json!({}));
    let entries = credentials.as_object_mut().ok_or("CredentialStoreInvalid")?;
    let mut store = STORE.write();
    let mut candidate = store.clone();
    for item in &mut candidate.items {
        let field = if item.token_field.is_empty() { DEFAULT_TOKEN_FIELD } else { &item.token_field };
        if let Some(env) = item.settings_config.get_mut("env").and_then(Value::as_object_mut) {
            if let Some(key) = env.remove(field).and_then(|v| v.as_str().map(str::to_owned)) {
                if !key.is_empty() { entries.insert(pi_translate::credential_id(&item.id).into(), json!({"type":"api_key","key":key})); }
            }
            // A provider has one credential; duplicate Anthropic key aliases are not persisted.
            env.remove(DEFAULT_TOKEN_FIELD);
            env.remove(API_KEY_FIELD);
        }
    }
    let mut value = serde_json::to_value(&candidate).map_err(|_| "ProviderStoreInvalid")?;
    value["credentials"] = credentials;
    atomic_write(&path, &serde_json::to_string_pretty(&value).map_err(|_| "ProviderStoreInvalid")?)
        .map_err(|_| "ProviderStoreWriteFailed")?;
    *store = candidate;
    Ok(())
}

