                "ANTHROPIC_BASE_URL": "https://a.example.com",
                "ANTHROPIC_AUTH_TOKEN": "sk-keep-me-abcd",
            }}),
        );
        // 前端拿到的就是打了码的那份;只改模型名后整份回传。
